import{_ as t,C as s,o,c as i,j as e,a as d,E as p,a2 as l}from"./chunks/framework.CQjSGuJt.js";const y=JSON.parse('{"title":"5. Art direction","description":"","frontmatter":{},"headers":[],"relativePath":"gdd/art.md","filePath":"gdd/art.md"}'),c={name:"gdd/art.md"};function r(h,n,g,u,b,m){const a=s("Badge");return o(),i("div",null,[n[0]||(n[0]=e("h1",{id:"_5-art-direction",tabindex:"-1"},[d("5. Art direction "),e("a",{class:"header-anchor",href:"#_5-art-direction","aria-label":'Permalink to "5. Art direction"'},"​")],-1)),p(a,{type:"tip",text:"Live"}),n[1]||(n[1]=l(' Asset hiện tại cắt từ ảnh mẫu <code>art/reference/gameplay-1080x1920.webp</code> bằng <code>art/tools/cut_assets.py</code>: khung HUD, nút booster, nút cài đặt, thân xe ngang (kéo dài thành 4 bể), 2 xe dọc từ <code>art/reference/bus-vertical.webp</code> (<code>rot</code> 90 = đuôi xe quay xuống, 270 = đầu xe quay xuống; cũng kéo dài thành 4 bể), biển trạm xe, ống vào/ra, viền san hô của nền. 8 con cá hề cùng dáng, đổi màu, tạo bằng ChatGPT (<code>art/generated/fish-clown-set.png</code>, xem Nhật ký asset). Bể kính, nước, ống nước, bọt, pháo giấy vẽ bằng code (<code>src/game/textures.ts</code>).<p>Prompt tạo asset gốc (lấy từ <code>ART_PROMPTS.md</code> của bản Fish Bus) giữ lại bên dưới để tạo asset mới cùng phong cách.</p><p><strong>Phong cách chung:</strong> casual mobile puzzle game art, glossy 3D cartoon render, soft studio lighting, bright saturated colors, clean edges.</p><p>Asset tạo bằng ChatGPT, <strong>đính kèm ảnh mẫu của game</strong> để giữ cùng phong cách, nền xanh lá thuần (#00FF00) để tách nền.</p><h2 id="_5-1-ca-moi-mau-1-anh-fish-red-png-fish-yellow-png-fish-green-png-fish-blue-png-fish-purple-png" tabindex="-1">5.1 Cá (mỗi màu 1 ảnh): <code>fish_red.png</code>, <code>fish_yellow.png</code>, <code>fish_green.png</code>, <code>fish_blue.png</code>, <code>fish_purple.png</code> <a class="header-anchor" href="#_5-1-ca-moi-mau-1-anh-fish-red-png-fish-yellow-png-fish-green-png-fish-blue-png-fish-purple-png" aria-label="Permalink to &quot;5.1 Cá (mỗi màu 1 ảnh): `fish_red.png`, `fish_yellow.png`, `fish_green.png`, `fish_blue.png`, `fish_purple.png`&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A single cute cartoon clownfish for a casual mobile puzzle game, side view facing RIGHT,</span></span>\n<span class="line"><span>glossy 3D cartoon render, chunky rounded body, two white stripes with thin black outlines,</span></span>\n<span class="line"><span>big friendly eye, small fins with dark edges. Body color: RED-ORANGE.</span></span>\n<span class="line"><span>Centered, whole fish visible, nothing else in the image, plain flat pure green (#00FF00) background,</span></span>\n<span class="line"><span>no shadow, no text. Square image 1024x1024.</span></span></code></pre></div><p>Đổi <code>RED-ORANGE</code> thành <code>YELLOW</code>, <code>GREEN</code>, <code>BLUE</code>, <code>PURPLE</code> cho các file còn lại.</p><h2 id="_5-2-xe-buyt-bus-4-png-va-bus-3-png-neu-muon" tabindex="-1">5.2 Xe buýt: <code>bus_4.png</code> (và <code>bus_3.png</code> nếu muốn) <a class="header-anchor" href="#_5-2-xe-buyt-bus-4-png-va-bus-3-png-neu-muon" aria-label="Permalink to &quot;5.2 Xe buýt: `bus_4.png` (và `bus_3.png` nếu muốn)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A purple cartoon bus seen from a high top-down 3/4 view (camera looking down at ~70 degrees),</span></span>\n<span class="line"><span>for a casual mobile puzzle game, glossy 3D render. The bus is long and horizontal, front on the LEFT,</span></span>\n<span class="line"><span>rear on the RIGHT. Its roof is a flat recessed tray that holds 4 EMPTY square glass slots in a row</span></span>\n<span class="line"><span>(the slots must be empty dark blue holes, no fish, no water). Small yellow headlights on the left,</span></span>\n<span class="line"><span>red tail lights on the right, small orange side lights, black wheels peeking out at the bottom.</span></span>\n<span class="line"><span>Plain flat pure green (#00FF00) background, no ground, no shadow, no text. Image 1536x640.</span></span></code></pre></div><h2 id="_5-3-nen-đay-bien-background-png" tabindex="-1">5.3 Nền đáy biển: <code>background.png</code> <a class="header-anchor" href="#_5-3-nen-đay-bien-background-png" aria-label="Permalink to &quot;5.3 Nền đáy biển: `background.png`&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Top-down view of a bright tropical seabed for a casual mobile puzzle game background,</span></span>\n<span class="line"><span>glossy cartoon style, light turquoise water, sandy patches, colorful corals (pink, orange, purple,</span></span>\n<span class="line"><span>teal), starfish, shells and small rocks placed ONLY along the left, right, top and bottom borders.</span></span>\n<span class="line"><span>The large CENTER area must be empty open water (it will be covered by the gameplay board).</span></span>\n<span class="line"><span>No fish, no text, no UI. Portrait 1080x1920.</span></span></code></pre></div><h2 id="_5-4-nut-ui-tuy-chon-btn-undo-png-btn-shuffle-png-btn-bus-png-btn-settings-png" tabindex="-1">5.4 Nút UI (tuỳ chọn): <code>btn_undo.png</code>, <code>btn_shuffle.png</code>, <code>btn_bus.png</code>, <code>btn_settings.png</code> <a class="header-anchor" href="#_5-4-nut-ui-tuy-chon-btn-undo-png-btn-shuffle-png-btn-bus-png-btn-settings-png" aria-label="Permalink to &quot;5.4 Nút UI (tuỳ chọn): `btn_undo.png`, `btn_shuffle.png`, `btn_bus.png`, `btn_settings.png`&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A single glossy rounded-square game button icon for a casual mobile puzzle game,</span></span>\n<span class="line"><span>purple with gold rim, white icon of [UNDO ARROW / SHUFFLE ARROWS / BUS / GEAR] in the center,</span></span>\n<span class="line"><span>3D cartoon style, soft highlight on top. Plain flat pure green (#00FF00) background, no text.</span></span>\n<span class="line"><span>Square 512x512.</span></span></code></pre></div><p>Nếu ảnh ra khác góc nhìn, nhắc thêm: &quot;same camera angle and style as the attached reference&quot;.</p><h2 id="_5-5-nhat-ky-asset" tabindex="-1">5.5 Nhật ký asset <a class="header-anchor" href="#_5-5-nhat-ky-asset" aria-label="Permalink to &quot;5.5 Nhật ký asset&quot;">​</a></h2><p>Asset mới tạo bằng ChatGPT theo <a href="./../guide/assets">quy trình này</a>.</p><table tabindex="0"><thead><tr><th>Ngày</th><th>Asset</th><th>Phiếu yêu cầu</th><th>Ảnh mẫu</th><th>Ghi chú</th></tr></thead><tbody><tr><td>2026-10-23</td><td>8 cá hề cùng dáng (thay 8 loài cá cũ)</td><td><code>art/requests/fish-clown-set.md</code></td><td>gameplay-1080x1920, fish-sheet</td><td>Nền xám vì có cá xanh lá</td></tr><tr><td>2026-10-23</td><td>Bàn tay hướng dẫn 2 trạng thái (giơ lên / ấn xuống)</td><td><code>art/requests/hand-pointer.md</code></td><td>gameplay-1080x1920</td><td>Lần 2: mu bàn tay hướng ra (lần 1 lộ lòng bàn tay)</td></tr><tr><td>2026-10-23</td><td>7 cá hề màu mới (brown, white, black, gray, sky, lime, navy)</td><td><code>art/requests/fish-clown-set-2.md</code></td><td>fish-clown-set.png</td><td>Nền hồng cánh sen vì có cá trắng / xám / đen</td></tr></tbody></table>',29))])}const _=t(c,[["render",r]]);export{y as __pageData,_ as default};
